import { isAbsolute, join, relative, sep } from 'path'
import { getCcHahaDir } from './envUtils.js'

/**
 * Root directory (across all sessions) where the ImageGen/ImageEdit tools save
 * their output — `<ccHahaDir>/generated-images/`. Mirrors the per-session dir
 * built in src/tools/ImageGenTool/backend.ts (defaultOutputDir), minus the
 * session segment so the check covers images generated by any session.
 */
export function getGeneratedImagesRootDir(): string {
  return join(getCcHahaDir(), 'generated-images')
}

/**
 * True when an absolute path sits inside the generated-images root. Uses
 * path.relative containment (empty / non-`..` / non-absolute) so it is robust
 * to `..` traversal and Windows separators. Case sensitivity follows the
 * platform's path semantics via relative().
 */
export function isGeneratedImagePath(absPath: string): boolean {
  const root = getGeneratedImagesRootDir()
  const rel = relative(root, absPath)
  // Escape only when rel is empty (the root itself), an absolute path (different
  // drive), or steps out of the root. Check `..` as a full path segment (=== '..'
  // or '..' + sep) rather than a prefix, so a child literally named "..foo.png"
  // is not misread as traversal. Mirrors backend.ts isPathInside.
  return (
    rel !== '' &&
    rel !== '..' &&
    !rel.startsWith(`..${sep}`) &&
    !isAbsolute(rel)
  )
}
